#ifndef FIXEDFANN
  static int FANN_API internal_callback(struct fann *ann, struct fann_train_data *train,
                                        unsigned int max_epochs,
                                        unsigned int epochs_between_reports, float desired_error,
                                        unsigned int epochs);
