FANN_EXTERNAL void FANN_API fann_set_cascade_activation_functions(
    struct fann *ann, enum fann_activationfunc_enum *cascade_activation_functions,
    unsigned int cascade_activation_functions_count);

FANN_EXTERNAL void FANN_API
fann_set_cascade_activation_steepnesses(struct fann *ann, fann_type *cascade_activation_steepnesses,
                                        unsigned int cascade_activation_steepnesses_count);

endpoints.code:
// Choose a valid network type
FANN::network_type_enum net_type = ( (*FUZZ_PARAM(unsigned int)) % 2 == 0 ) ? FANN::LAYER : FANN::SHORTCUT;
// Choose a sensible number of layers: at least input and output, cap small for speed
unsigned int num_layers = (unsigned int)(*FUZZ_PARAM(unsigned int) % 5) + 2; // [2,6]
// Build a layers array of size num_layers with small positive sizes
std::vector<unsigned int> layers(num_layers);
{
  // Fill from fuzz bytes; ensure each layer size >= 1 and <= 64
  std::string bytes = FUZZ_PARAM_STR();
  size_t need = num_layers * sizeof(unsigned int);
  if (bytes.size() < need) {
    // pad deterministically if not enough bytes
    bytes.append(need - bytes.size(), '\0');
  }
  const unsigned int *raw = reinterpret_cast<const unsigned int*>(bytes.data());
  for (unsigned int i = 0; i < num_layers; ++i) {
    unsigned int v = raw[i];
    layers[i] = (v % 64u) + 1u;
  }
}
// Construct the network on the heap so it can be tracked by the object pool
FANN::neural_net *net = new FANN::neural_net(net_type, num_layers, layers.data());
// Set initialized attribute for downstream stubs
FUZZ_SET_ATTR_INT(net, "initialized", 1);
// Validation: constructor should yield a usable object; we assert the pointer exists
FUZZ_ASSERT(net != NULL, "neural_net constructor returned null");
// net is returned as output for reuse

// Destruction invalidates the object; do not return it as an output
// Drop any fuzzer attributes by deleting the object
// After this call, using net is invalid per API
